import { Router } from 'express';
import { requireAuth } from '../middlewares/auth';
import { validate } from '../middlewares/validate';
import { createOrderSchema } from '../schemas/order';
import { createOrderController } from '../controllers/orders';

export const ordersRouter = Router();

// POST /api/orders: autentica, valida o corpo e cria o pedido
ordersRouter.post(
  '/',
  requireAuth,
  validate(createOrderSchema),
  createOrderController,
);

import type { Request, Response, NextFunction } from 'express';
import { verifyAccessToken } from '../lib/auth0';

export async function requireAuth(req: Request, res: Response, next: NextFunction) {
  const header = req.headers.authorization ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'unauthorized' });

  try {
    const claims = await verifyAccessToken(token); // JWKS do Auth0, com cache
    req.user = { id: claims.sub, email: claims.email };
    return next();
  } catch {
    return res.status(401).json({ error: 'invalid_token' });
  }
}

import type { Request, Response, NextFunction } from 'express';
import type { ZodSchema } from 'zod';

export const validate = (schema: ZodSchema) =>
  (req: Request, res: Response, next: NextFunction) => {
    const parsed = schema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(422).json({ error: 'invalid_body', issues: parsed.error.issues });
    }
    req.body = parsed.data;
    return next();
  };

import type { Request, Response, NextFunction } from 'express';
import { createOrder } from '../actions/create-order';

export async function createOrderController(req: Request, res: Response, next: NextFunction) {
  try {
    const order = await createOrder({ userId: req.user.id, items: req.body.items });
    return res.status(201).json(order);
  } catch (err) {
    return next(err); // vai para o error handler e para o Sentry
  }
}

import { db } from '../db';
import { ordersRepo } from '../repositories/orders';
import { stripe } from '../lib/stripe';
import { publish } from '../lib/queue';

export async function createOrder({ userId, items }: CreateOrderInput) {
  const products = await ordersRepo.findProducts(items.map(i => i.productId));
  const total = items.reduce((sum, i) => sum + products[i.productId].price * i.qty, 0);

  const order = await ordersRepo.insert({ userId, items, total, status: 'pending' });

  const payment = await stripe.paymentIntents.create({
    amount: total,
    currency: 'brl',
    metadata: { orderId: order.id },
  });

  await publish('order.created', { orderId: order.id });
  return { ...order, clientSecret: payment.client_secret };
}

import { db } from '../db';

export const ordersRepo = {
  async findProducts(ids: string[]) {
    const rows = await db.query(
      'SELECT id, price, stock FROM products WHERE id = ANY($1)',
      [ids],
    );
    return Object.fromEntries(rows.map(r => [r.id, r]));
  },

  async insert(order: NewOrder) {
    const [row] = await db.query(
      `INSERT INTO orders (user_id, items, total, status)
       VALUES ($1, $2, $3, $4) RETURNING *`,
      [order.userId, JSON.stringify(order.items), order.total, order.status],
    );
    return row;
  },
};

export async function publish(topic: string, payload: unknown) {
  const ch = await channel();
  ch.publish('orders', topic, Buffer.from(JSON.stringify(payload)), { persistent: true });
}

import type { Request, Response, NextFunction } from 'express';
import { redis } from '../lib/redis';

// Reaproveita a resposta quando o cliente repete a mesma Idempotency-Key.
export async function idempotency(req: Request, res: Response, next: NextFunction) {
  const key = req.header('Idempotency-Key');
  if (!key) return res.status(400).json({ error: 'missing_idempotency_key' });

  const cacheKey = `idem:${req.user.id}:${key}`;
  const saved = await redis.get(cacheKey);
  if (saved) return res.status(200).json(JSON.parse(saved));

  const json = res.json.bind(res);
  res.json = body => {
    if (res.statusCode < 300) redis.set(cacheKey, JSON.stringify(body), 'EX', 86400);
    return json(body);
  };
  return next();
}

import { db } from '../db';
import { publish } from '../lib/queue';

// Roda a cada segundo no worker: publica o que está no outbox e marca como enviado.
export async function relayOutbox() {
  const rows = await db.query(
    `SELECT id, topic, payload FROM outbox
     WHERE sent_at IS NULL ORDER BY id LIMIT 100 FOR UPDATE SKIP LOCKED`,
  );
  for (const r of rows) {
    await publish(r.topic, r.payload);
    await db.query('UPDATE outbox SET sent_at = now() WHERE id = $1', [r.id]);
  }
}

