import { db } from '../db';
import { ordersRepo } from '../repositories/orders';
import { stripe } from '../lib/stripe';

export async function createOrder({ userId, items, idempotencyKey }: CreateOrderInput) {
  // Pedido e evento na mesma transação (outbox): nenhum evento se perde.
  const order = await db.transaction(async tx => {
    const products = await ordersRepo.findProducts(items.map(i => i.productId), tx);
    const total = items.reduce((sum, i) => sum + products[i.productId].price * i.qty, 0);
    const row = await ordersRepo.insert({ userId, items, total, status: 'pending' }, tx);
    await tx.query('INSERT INTO outbox (topic, payload) VALUES ($1, $2)',
      ['order.created', { orderId: row.id }]);
    return row;
  });

  const payment = await stripe.paymentIntents.create(
    { amount: order.total, currency: 'brl', metadata: { orderId: order.id } },
    { idempotencyKey, timeout: 8000 },
  );
  return { ...order, clientSecret: payment.client_secret };
}

